/* NOTE BENCH, SAP, FOR THE CONSOLE. Generated by
 * scripts/bench/build-console.mjs; edit the cases, the checks or the runner,
 * never this file.
 *
 * Open tools.nooutco.me/notes/sap/ logged in, keep the tab in front, and paste
 * the whole file into the console. It runs the 3 invented cases in
 * scripts/bench/cases/sap.json the way a user does: types each one, presses
 * Generate, answers the page's questions from the case's hidden details,
 * Sends, reads the note back and scores it. Between cases it presses Clear.
 *
 * It costs 3 drafts plus their question rounds, and sends only the
 * invented cases below. The results land on your clipboard. */
(() => {
  /* Chrome lends the console's copy() only while pasted code first runs, so
     it is taken before the first await. The report also stays on window. */
  const copyNow = typeof copy === 'function' ? copy : null;
  const CASES = [
    {
      "id": "sap-aac-manding",
      "page": "/notes/sap/",
      "fields": {
        "Treatment Goal": "Client will independently request preferred items using a 2-button AAC page (more, help) in 8 of 10 opportunities across 3 consecutive sessions, absent behaviors targeted for reduction, as measured by direct observation during play and snack.",
        "SAP Specifications": "already taps \"more\" with a gesture prompt at snack. grabs items from adult hands when the demand goes up. tried a PECS binder last auth, abandoned it, too slow for him. works for the tablet and goldfish crackers. has to work at the clinic with 2 staff and at home with mom. 60 min sessions, one technician. use most-to-least for \"help\", he gets frustrated with errors. mastery as in the goal."
      },
      "truth": [
        {
          "about": [
            "baseline",
            "currently",
            "how often",
            "right now",
            "rate"
          ],
          "answer": "Right now he taps more about 3 of 10 times at snack with a gesture; help he does not use at all."
        },
        {
          "about": [
            "reinforc",
            "prefer",
            "reward"
          ],
          "answer": "Tablet for 30 seconds or one goldfish cracker per request."
        },
        {
          "about": [
            "behavior",
            "grab",
            "problem",
            "aggress"
          ],
          "answer": "Grabbing, about 5 times a session, no aggression."
        }
      ],
      "expect": {
        "mentions": [
          [
            "8 of 10",
            "8 out of 10",
            "8/10"
          ],
          [
            "tablet",
            "iPad"
          ],
          [
            "most-to-least",
            "most to least"
          ],
          "help"
        ],
        "forbid": [
          "The Behavior Analyst"
        ]
      }
    },
    {
      "id": "sap-two-step-instructions",
      "page": "/notes/sap/",
      "fields": {
        "Treatment Goal": "Client will follow 2-step related instructions (e.g., get your shoes and sit down) within 5 seconds in 80% of opportunities across 2 consecutive sessions, with 2 different staff, during home and school routines.",
        "SAP Specifications": "follows 1-step instructions reliably, breaks down on step 2, usually does step 1 then wanders. responds best when the instruction is paired with a point. walks off when demands stack up, no aggression. home sessions 2 hrs, 3x a week, plus 1 school day with a shadow. generalize to mom and his teacher. maintenance probes weekly for 4 weeks after mastery. error correction: never repeat the instruction more than once."
      },
      "truth": [
        {
          "about": [
            "which instructions",
            "examples",
            "targets",
            "start with"
          ],
          "answer": "Start with get X and bring it to me, put X away and come here, wash hands and sit down."
        },
        {
          "about": [
            "baseline",
            "currently",
            "how often",
            "right now"
          ],
          "answer": "About 2 of 10 two-step instructions done fully right now."
        }
      ],
      "expect": {
        "mentions": [
          [
            "5 second",
            "5-second",
            "five second",
            "five-second"
          ],
          [
            "80%",
            "80 percent"
          ],
          "teacher",
          [
            "4 week",
            "4-week",
            "four week",
            "four-week"
          ],
          "point"
        ],
        "forbid": [
          "The Behavior Analyst"
        ]
      }
    },
    {
      "id": "sap-thin-waiting",
      "page": "/notes/sap/",
      "fields": {
        "Treatment Goal": "Client will tolerate a 2-minute wait for a preferred item without behaviors in 4 of 5 opportunities across 3 sessions.",
        "SAP Specifications": "screams when told wait. home only."
      },
      "truth": [
        {
          "about": [
            "current",
            "how long",
            "baseline",
            "now",
            "tolerat"
          ],
          "answer": "He waits about 10 seconds before screaming."
        },
        {
          "about": [
            "reinforc",
            "prefer",
            "item"
          ],
          "answer": "Tablet and the swing in the yard."
        },
        {
          "about": [
            "tried",
            "timer",
            "history",
            "in the past",
            "previous"
          ],
          "answer": "A visual timer was tried once and he threw it."
        }
      ],
      "expect": {
        "mentions": [
          [
            "4 of 5",
            "4 out of 5",
            "4/5"
          ],
          "wait"
        ],
        "forbid": [
          "The Behavior Analyst"
        ]
      }
    }
  ];

  // Each module keeps its own scope, as it has on disk.
  const checkParentDraft = (() => {
    /* What a right parent note must show, checked against a draft.
     *
     * Written 2026-10-03 from one production parent note that came out wrong, as
     * step 9 of the plan Kaleb approved. Each check is one of his rulings on that
     * note, so a failure names the ruling it breaks. The cases live in
     * tests/fixtures/parent-note-shape.json; parent-note-shape.spec.js proves
     * these checks catch the failures the real note had, and the same checks can
     * score a live draft (see that spec's header for how).
     *
     * `draft` is the parent tool's normalized output: individualsPresent,
     * supportActivities, caregiverResponse, progressStatus, summary, followup,
     * hints. */
    
    const QUESTION_LINE = /^\s*(clarify|specify|(confirm|verify|determine|check|ask|identify) (whether|if)|find out (whether|if))\b|\?\s*$/i;
    
    const lc = (s) => String(s || '').toLowerCase();
    const anyOf = (v) => [].concat(v);
    
    function checkParentDraft(c, draft) {
      const e = c.expect || {};
      const fails = [];
      const summary = String(draft.summary || '');
      const all = `${summary}\n${draft.followup || ''}`;
    
      for (const name of e.goalNames || []) {
        if (!lc(summary).includes(lc(name))) fails.push(`goal not named in the summary: "${name}"`);
      }
      for (const claim of e.forbidCountClaims || []) {
        if (lc(summary).includes(lc(claim))) fails.push(`a goal count the list does not support: "${claim}"`);
      }
      for (const p of e.forbidPhrases || []) {
        if (lc(all).includes(lc(p))) fails.push(`a phrase that must not appear: "${p}"`);
      }
      if (e.promptLevelWithCount) {
        // count may list several ways to write the same count ("2 of 3", "2
        // trials"); Kaleb's first live run wrote one the single form missed.
        const { count, level } = e.promptLevelWithCount;
        const forms = anyOf(count);
        const sentences = summary.split(/(?<=[.!?])\s+/);
        const withCount = sentences.filter((s) => forms.some((f) => lc(s).includes(lc(f))));
        if (!withCount.length) fails.push(`the trial count ("${forms.join('" or "')}") is missing`);
        else if (!withCount.some((s) => lc(s).includes(lc(level)))) fails.push(`the trial count is written without the prompt level ("${level}") beside it`);
      }
    
      const present = draft.individualsPresent || [];
      for (const who of e.individualsInclude || []) if (!present.includes(who)) fails.push(`Individuals Present is missing "${who}"`);
      for (const who of e.individualsExclude || []) if (present.includes(who)) fails.push(`Individuals Present lists "${who}", whom the notes place out of the session`);
    
      if (e.caregiverResponse && draft.caregiverResponse !== e.caregiverResponse) {
        fails.push(`Caregiver Response picked "${draft.caregiverResponse}", expected "${e.caregiverResponse}"`);
      }
      if (e.progressStatus && draft.progressStatus !== e.progressStatus) {
        fails.push(`Progress Status picked "${draft.progressStatus}", expected "${e.progressStatus}"`);
      }
    
      const items = String(draft.followup || '').split('\n').map((s) => s.trim()).filter(Boolean);
      if (e.followupItems) {
        const [lo, hi] = e.followupItems;
        if (items.length < lo || items.length > hi) fails.push(`Follow Up has ${items.length} item(s), expected ${lo} to ${hi}`);
      }
      for (const line of items) if (QUESTION_LINE.test(line)) fails.push(`Follow Up holds a question to the author: "${line}"`);
      // An entry may list alternatives: ["BT", "technician"] is met by either.
      for (const entry of e.followupMentions || []) {
        const words = anyOf(entry);
        if (!items.some((l) => words.some((w) => lc(l).includes(lc(w))))) fails.push(`no Follow Up item mentions "${words.join('" or "')}"`);
      }
      return fails;
    }
    return checkParentDraft;
  })();

  const checkNote = (() => {
    /* THE BENCH'S CHECKS, one set for every tool.
     *
     * Each check is one of Kaleb's rulings or one point of his BT Session Note
     * Resources guide, so a failure names the rule it breaks. A case's `expect`
     * says which apply:
     *
     *   mentions   facts the note must carry. Each is a phrase, or a list of the
     *              plain forms that say the same fact (["dad", "father", "parent",
     *              "caregiver"]); any one form passes. A form counts at the start
     *              of a word, so "gesture" passes "gestures" and "turn" does not
     *              pass "return". A ruling stays one exact phrase ("full
     *              physical", "mastery criteria"). Kaleb's BT runs of 9 Oct 2026
     *              failed notes that said "new action sequences", the intake's own
     *              "new ones", where the case wanted "novel", and "His father"
     *              where it wanted "dad".
     *   forbid     phrases it must not (an invented fact, a hollow line, "was
     *              reinforced", "responded well")
     *   picks      { group: [labels that must be ticked] }
     *   notPicks   { group: [labels that must not be] }
     *   single     { group: label } for a single-select
     *   noData     true for BT: no percentage or a/b count in a narrative, because
     *              ReThink already pulls the data in (his guide)
     *   tasksOnly  narrative keys that hold tasks, never a question to the author
     *
     * And on every note: no opaque token left, no em dash, no blank single-select.
     * The parent tool's own checks (scripts/lib/parent-shape-checks.mjs) run too
     * when the case carries `parentExpect`. */
    
    const lc = (s) => String(s || '').toLowerCase();
    const forms = (m) => (Array.isArray(m) ? m : [m]);
    const QUESTION = /^\s*(clarify|specify|(confirm|verify|determine|check|ask|identify) (whether|if)|find out (whether|if))\b|\?\s*$/i;
    
    /* What the note says: its narratives, its picks and its goals table rows.
       Never the page around it. Kaleb's Assessment run on 9 Oct 2026 passed
       "neuropsych" only because the expert review panel showed "neuropsych - not
       recognized"; the note itself said "assessment report from May". So mentions
       and forbids read this, and the card's `all` text is left for the report. */
    function noteWords(note) {
      const picks = Object.values(note.picks || {}).flat();
      const rows = Object.values(note.tables || {}).flat();
      return [...Object.values(note.text || {}), ...picks, ...rows].join('\n');
    }
    
    /* The note as the parent checker reads it: narratives by key, picks by group,
       a single-select as its one label. */
    function flatDraft(note, singles = []) {
      const out = { ...note.text };
      for (const [group, on] of Object.entries(note.picks || {})) {
        out[group] = singles.includes(group) ? (on[0] || '') : on;
      }
      return out;
    }
    
    function checkNote(c, note) {
      const e = c.expect || {};
      const fails = [];
      const narratives = Object.values(note.text || {}).join('\n');
      const said = noteWords(note);
    
      for (const m of e.mentions || []) {
        if (!forms(m).some((f) => saysAtWordStart(said, f))) fails.push(`missing from the note: ${forms(m).map((f) => `"${f}"`).join(' or ')}`);
      }
      for (const f of e.forbid || []) if (lc(said).includes(lc(f))) fails.push(`must not appear: "${f}"`);
      for (const [group, labels] of Object.entries(e.picks || {})) {
        const on = (note.picks || {})[group] || [];
        for (const l of labels) if (!on.includes(l)) fails.push(`${group} is missing "${l}"`);
      }
      for (const [group, labels] of Object.entries(e.notPicks || {})) {
        const on = (note.picks || {})[group] || [];
        for (const l of labels) if (on.includes(l)) fails.push(`${group} wrongly has "${l}"`);
      }
      for (const [group, label] of Object.entries(e.single || {})) {
        const on = (note.picks || {})[group] || [];
        if (on[0] !== label) fails.push(`${group} picked "${on[0] || '(blank)'}", expected "${label}"`);
      }
      if (e.noData) {
        const hit = narratives.match(/\b\d+\s*\/\s*\d+\b|\b\d+(?:\.\d+)?\s*%|\b\d+ (?:of|out of) \d+\b/);
        if (hit) fails.push(`repeats data ReThink already pulls in: "${hit[0]}"`);
      }
      for (const key of e.tasksOnly || []) {
        for (const line of String((note.text || {})[key] || '').split('\n')) {
          if (line.trim() && QUESTION.test(line)) fails.push(`${key} holds a question to the author: "${line.trim()}"`);
        }
      }
      if (/\[\[T\d+\]\]/.test(said)) fails.push('an opaque token was left in the note');
      if (/\u2014/.test(narratives)) fails.push('an em dash in a narrative');
      for (const group of e.singlesNeverBlank || []) {
        if (!((note.picks || {})[group] || [])[0]) fails.push(`${group} left blank`);
      }
      if (c.parentExpect) fails.push(...checkParentDraft({ expect: c.parentExpect }, flatDraft(note, ['caregiverResponse', 'progressStatus'])));
      return fails;
    }
    return checkNote;
  })();

  /* THE BENCH IN HIS CONSOLE. Kaleb, 2026-10-04 (bench access, B): no bench
   * login; he pastes the bench into the console of a tool page he is logged in
   * on, one tool per sitting, as with the parent live script.
   *
   * This is lib/drive.mjs done from inside the page: the same steps a user takes
   * (fill the case, Generate, answer the page's questions from the case's truth,
   * Send, read the note card back), with plain DOM calls in place of Playwright.
   * Between cases it presses the page's own Clear, which drops the inputs, the
   * note and the scrub ledger; the confirm that Clear asks is answered yes for
   * that one press.
   *
   * The site refuses to be framed (X-Frame-Options DENY), so a case cannot run in
   * an iframe; Clear is what makes several cases one sitting.
   *
   * Built into scripts/bench/console/<tool>.js by scripts/bench/build-console.mjs,
   * which inlines the cases and lib/checks.mjs. This file must stay free of
   * imports: it is stringified into that script. */
  
  /* WHAT A USER TYPES WHEN THE PAGE HOLDS A ROUND THEY CANNOT ANSWER.
   *
   * Below the readiness bar the page refuses to draft until one question of the
   * first round is answered (his ruling of 2026-08-31, held in engine.jsx
   * gateHolds), and while it holds there is no Send at all, only the note that
   * says what opens it. A case's truth answers only what that session knew, so
   * a question it does not speak to used to leave the bench waiting on a Send
   * that could not appear: v3 on 9 Oct 2026, "timed out waiting for Send to
   * open". A user in that seat says there is nothing more and moves on, so the
   * bench does the same and records the round in `held`, where the report shows
   * it. Long enough (over 25 characters) to open the Send lock as typing does. */
  const HELD_ROUND_ANSWER = 'Nothing more to add from this session.';
  
  /* WHICH TRUTH ANSWERS WHICH QUESTION, one round at a time.
   *
   * A case's truth is the session as the technician remembers it, each fact with
   * the words a question about it would use (`about`). A question takes the fact
   * whose words it shares most, counted at the start of a word, and each fact
   * answers at most one question in a round. When two questions want the same
   * fact, the one that fits it best gets it. A question no fact fits is left
   * blank, as a technician who did not track that would leave it.
   *
   * Kaleb's BT runs on 9 Oct 2026 are why: the picker took the first fact sharing
   * any one word. Both school questions got the greeting answer ("Q2 answer
   * duplicates Q1 answer"), a question about past sessions got the precursor
   * answer and the note wrote it as history, and a question about what guidance
   * dad used got the coaching answer.
   *
   * IGNORED_ABOUT holds the words nearly every question in a case carries (who
   * was there, the behavior, "before", "prompt"), so sharing one says nothing
   * about which fact is asked for. The picker skips them, and the spec keeps
   * every case's `about` free of them. */
  const IGNORED_ABOUT = [
    'how', 'what', 'when', 'why', 'who', 'which', 'did', 'does', 'was', 'were',
    'before', 'after', 'said', 'say', 'session', 'client', 'he', 'she', 'him', 'her',
    'dad', 'mom', 'father', 'mother', 'parent', 'caregiver', 'prompt', 'hit',
  ];
  
  /* The phrase at the start of a word somewhere in the text, any case. Shared
     with lib/checks.mjs, which reads a note's mentions the same way. */
  function saysAtWordStart(text, phrase) {
    const at = String(text || '').toLowerCase();
    const p = String(phrase || '').toLowerCase();
    for (let i = at.indexOf(p); i !== -1; i = at.indexOf(p, i + 1)) {
      if (i === 0 || !/[a-z0-9]/.test(at[i - 1])) return true;
    }
    return false;
  }
  
  function pickAnswers(questions, truth) {
    const lc = (s) => String(s || '').toLowerCase();
    const facts = truth || [];
    const fits = [];
    questions.forEach((q, qi) => facts.forEach((t, ti) => {
      const on = (t.about || []).filter((k) => !IGNORED_ABOUT.includes(lc(k)) && saysAtWordStart(q, k));
      if (on.length) fits.push({ qi, ti, on });
    }));
    // Best fit first; a tie goes to the earlier question, then the earlier fact.
    fits.sort((a, b) => b.on.length - a.on.length || a.qi - b.qi || a.ti - b.ti);
    const used = new Set();
    const picked = questions.map(() => ({ truth: null, matchedOn: [], answer: null }));
    for (const f of fits) {
      if (picked[f.qi].answer !== null || used.has(f.ti)) continue;
      used.add(f.ti);
      picked[f.qi] = { truth: f.ti, matchedOn: f.on, answer: facts[f.ti].answer };
    }
    return picked;
  }
  
  /* Which truth answered which question, a line each, so a mismatch shows in
     the run's log as well as in the report's `asked`. */
  function answerLines(asked) {
    return (asked || []).map((a) => `  round ${a.round}: ${a.question}\n    ${a.answer
      ? `truth ${a.truth} (on ${(a.matchedOn || []).join(', ')}): ${a.answer}`
      : 'left blank: no truth fits'}`);
  }
  
  /* One question on its own: the fact that fits it, or null. */
  function answerFor(question, truth) {
    return pickAnswers([question], truth)[0].answer;
  }
  
  /* THE NOTE CARD AS A CLINICIAN COPIES IT: picks per group, text per narrative,
   * the goals table's rows, and `all`, the whole card in its order, each section
   * under its own heading. The checks read the first three; `all` is for a
   * person reading the report.
   *
   * A narrative the corrections pass changed is drawn as marks in place of its
   * textarea (engine.jsx renderSectionContent), and that box "holds exactly what
   * Copy gives you" (corrections-view.jsx). Reading textareas alone missed every
   * such section: on 9 Oct 2026 the live summaries of v1, v2 and v4 and the
   * Follow Ups of v2 and v4 read as empty, so every goal was "not named". The
   * box's controls are left out, and so is the rail of removed words under it,
   * which the clipboard does not carry either.
   *
   * `all` is built section by section. It was the card's innerText with every
   * field's value added at the end, and innerText never carries a textarea's
   * value, so on Kaleb's BT runs of 9 Oct 2026 every narrative read as if it sat
   * under Summary of Concerns, the last heading. The tool lays them out right.
   * A multi-select gives only its ticked labels, as the form will.
   *
   * Exported for lib/drive.mjs, which runs this same function in the page, so
   * the two benches cannot read a note two ways. Self-contained for that reason. */
  function readNoteCard(card) {
    const CONTROLS = 'button, input, textarea, [data-correction-pop], [data-correction-ask-box]';
    const boxText = (box) => {
      const copy = box.cloneNode(true);
      copy.querySelectorAll(CONTROLS).forEach((n) => n.remove());
      return copy.textContent;
    };
    // A section drawn some other way (the goals table, the facts) as shown, with
    // its fields' values, which innerText does not carry, kept in that section.
    const shownIn = (sec, title) => {
      let shown = sec.innerText;
      sec.querySelectorAll('button, [data-corrections-rail]').forEach((n) => {
        if (n.innerText) shown = shown.replace(n.innerText, '');
      });
      shown = shown.replace(title, '');
      const fields = [...sec.querySelectorAll('textarea, input:not([type]), input[type="text"]')].map((t) => t.value);
      return [shown, ...fields].map((s) => s.trim()).filter(Boolean).join('\n');
    };
    const picks = {};
    card.querySelectorAll('[data-section-id]').forEach((sec) => {
      const on = [...sec.querySelectorAll('[data-option][data-on="1"]')].map((o) => o.getAttribute('data-option'));
      if (sec.querySelector('[data-option]')) picks[sec.getAttribute('data-section-id')] = on;
    });
    const text = {};
    const tables = {};
    const parts = [];
    card.querySelectorAll('[data-section-key]').forEach((sec) => {
      const key = sec.getAttribute('data-section-key');
      const title = sec.getAttribute('data-section-title') || '';
      const say = (body) => parts.push([title, body].filter(Boolean).join('\n'));
      // A single-select shows only its chosen answer, marked for reading.
      const single = sec.querySelector('[data-single-answer]');
      if (single) { picks[key] = [single.getAttribute('data-single-answer')]; say(picks[key][0]); return; }
      if (sec.querySelector('[data-section-id] [data-option]') || picks[key]) {
        say([...sec.querySelectorAll('[data-option][data-on="1"]')].map((o) => o.getAttribute('data-option')).join('\n'));
        return;
      }
      const marked = sec.querySelector('[data-corrections-section]');
      if (marked) { text[key] = boxText(marked); say(text[key]); return; }
      // The goals table: its rows' cells, never the goal picker above it.
      const rows = [...sec.querySelectorAll('[data-goal-row]')];
      if (rows.length) {
        tables[key] = rows.map((r) => [...r.querySelectorAll('textarea, input:not([type]), input[type="text"]')].map((t) => t.value.trim()).filter(Boolean).join(' | '));
        say(tables[key].join('\n'));
        return;
      }
      const ta = sec.querySelector('textarea');
      if (ta) { text[key] = ta.value; say(text[key]); return; }
      say(shownIn(sec, title));
    });
    return { picks, text, tables, all: parts.join('\n\n') };
  }
  
  async function benchInPage(CASES, checkNote, opts = {}) {
    const LIMIT = opts.timeoutMs || 180000;
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    const words = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;
    const $ = (sel) => document.querySelector(sel);
    const $$ = (sel) => [...document.querySelectorAll(sel)];
    const shown = (el) => !!el && el.getClientRects().length > 0;
    const until = async (fn, what, ms = LIMIT) => {
      const end = Date.now() + ms;
      for (;;) {
        const v = fn();
        if (v) return v;
        if (Date.now() > end) throw new Error(`timed out waiting for ${what}`);
        await sleep(250);
      }
    };
  
    /* React keeps a field's value in state, so the value is set through the
       element's own setter and announced with an input event, as typing does. */
    const type = (el, text) => {
      const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
      Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, text);
      el.dispatchEvent(new Event('input', { bubbles: true }));
    };
    const enter = (el) => el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true, cancelable: true }));
    const button = (re, root = document) => [...root.querySelectorAll('button')].find((b) => re.test(b.textContent.trim()) && shown(b));
  
    /* The page's in-flight calls, counted so the passes after the first draft
       (self-revision, corrections) can settle before the note is read. Put back
       when the run ends. */
    let inFlight = 0;
    const realFetch = window.fetch;
    window.fetch = function (...args) {
      inFlight += 1;
      return realFetch.apply(this, args).finally(() => { inFlight -= 1; });
    };
    const settle = async () => {
      const end = Date.now() + (opts.settleMs || 60000);
      let quiet = 0;
      while (Date.now() < end && quiet < 6) { quiet = inFlight ? 0 : quiet + 1; await sleep(250); }
    };
  
    const clear = async () => {
      const b = [...document.querySelectorAll('button')].find((x) => x.textContent.trim() === 'Clear' && shown(x));
      if (!b) return;
      const realConfirm = window.confirm;
      window.confirm = () => true;
      try { b.click(); } finally { window.confirm = realConfirm; }
      await until(() => !$('[data-testid="generated-note"]') && !$('[data-panel-question]'), 'the page to clear', 10000);
    };
  
    const fieldNamed = (label) => {
      const re = new RegExp(label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
      return $$('textarea, input').find((el) => {
        const name = el.getAttribute('aria-label') || (el.labels && el.labels[0] ? el.labels[0].textContent : '') || el.placeholder || '';
        return re.test(name) && shown(el);
      });
    };
  
    const fill = async (c) => {
      // A toggle is its label paragraph followed by a row of buttons.
      for (const [label, value] of Object.entries(c.toggles || {})) {
        const p = $$('p').find((x) => x.textContent.includes(label));
        const row = p && p.nextElementSibling;
        const b = row && [...row.querySelectorAll('button')].find((x) => x.textContent.trim() === value);
        if (!b) throw new Error(`no "${value}" button under "${label}"`);
        b.click();
      }
      for (const [field, value] of Object.entries(c.choices || {})) {
        const b = $(`[data-arrival-field="${field}"] [data-arrival="${value}"]`);
        if (!b) throw new Error(`no "${value}" choice for ${field}`);
        b.click();
      }
      // Waited for, not looked up once: after a Clear the form is drawn again,
      // and on a slow run the box is not there yet the moment Clear returns.
      for (const [label, text] of Object.entries(c.fields || {})) {
        const el = await until(() => fieldNamed(label), `a field named "${label}" on this page`, 10000);
        type(el, text);
      }
      await sleep(300);
    };
  
    const clearGates = async () => {
      await sleep(500);
      const ack = $('#notes-ack-go');
      if (shown(ack)) { const cb = $('#notes-ack-cb'); if (cb && !cb.checked) cb.click(); ack.click(); }
      const review = $('#notes-scrub-go');
      if (shown(review)) review.click();
    };
  
    const openPanel = async () => {
      if (shown($('.revision-input'))) return;
      const fab = $('.revision-fab');
      if (shown(fab)) fab.click();
      await until(() => shown($('.revision-input')), 'the panel to open', 5000);
    };
  
    const readNote = () => readNoteCard($('[data-testid="generated-note"]'));
    const held = () => shown($('[data-skip-held]'));
  
    const runCase = async (c) => {
      const started = Date.now();
      await clear();
      await fill(c);
      const go = button(/^(Generate|Regenerate)(?! Prompt)/);
      if (!go) throw new Error('no Generate button: log in first');
      go.click();
      await clearGates();
  
      const typed = { intake: Object.values(c.fields || {}).reduce((n, t) => n + words(t), 0), answers: 0 };
      const asked = [];
      const heldRounds = [];
      const noteUp = () => shown($('[data-testid="generated-note"]'));
      await until(() => noteUp() || $('[data-panel-question]'), 'the first questions or the note');
  
      // Up to 3 rounds, the page's own cap.
      for (let round = 0; round < 3 && !noteUp(); round++) {
        if (!$('[data-panel-question]')) break;
        await openPanel();
        const loose = [];
        let answeredAny = false;
        const shownQs = $$('[data-panel-question]').map((el) => ({ i: el.getAttribute('data-panel-question'), question: el.innerText.split('\n')[0] }));
        const picked = pickAnswers(shownQs.map((q) => q.question), c.truth);
        for (const [n, { i, question }] of shownQs.entries()) {
          const { answer, truth, matchedOn } = picked[n];
          asked.push({ round: round + 1, question, answered: !!answer, truth, matchedOn, answer });
          if (!answer) continue;
          answeredAny = true;
          typed.answers += words(answer);
          const own = $(`[data-suggestion-own="${i}:own"]`);
          if (shown(own)) { type(own, answer); enter(own); } else loose.push(answer);
        }
        // A held round with nothing answered: the user's "nothing more" (above).
        if (!answeredAny && held()) {
          heldRounds.push(round + 1);
          typed.answers += words(HELD_ROUND_ANSWER);
          loose.push(HELD_ROUND_ANSWER);
        }
        if (loose.length) type($('.revision-input'), loose.join(' '));
        // Send opens once enough is written, or when the page's lock runs out.
        const send = await until(() => { const b = $('.revision-send'); return b && !b.disabled && b; }, 'Send to open')
          .catch((err) => {
            throw held() ? new Error(`${err.message}: the page held the round and nothing answered it`) : err;
          });
        send.click();
        const last = asked.length ? asked[asked.length - 1].question : '';
        await until(() => noteUp() || ($('[data-panel-question]') && $('[data-panel-question]').innerText.split('\n')[0] !== last), 'the next round or the note').catch(() => {});
      }
      await until(noteUp, 'the note');
      await settle();
      return { id: c.id, note: readNote(), asked, held: heldRounds, typed: { ...typed, total: typed.intake + typed.answers }, seconds: Math.round((Date.now() - started) / 1000) };
    };
  
    const results = [];
    const log = opts.log || ((s) => console.log(s));
    log(`Running ${CASES.length} cases on this page, one after another. Keep this tab in front; a hidden tab slows its timers.`);
    try {
      for (const [n, c] of CASES.entries()) {
        try {
          const out = await runCase(c);
          const fails = checkNote(c, out.note);
          results.push({ ...out, fails });
          log(`${n + 1} of ${CASES.length}: ${c.id}, ${fails.length ? 'FAIL' : 'pass'}, typed ${out.typed.total} words, ${new Set(out.asked.map((a) => a.round)).size} round(s)${out.held.length ? `, held round ${out.held.join(' and ')} answered "${HELD_ROUND_ANSWER}"` : ''}, ${out.seconds}s`);
          if (out.asked.length) log(answerLines(out.asked).join('\n'));
        } catch (err) {
          results.push({ id: c.id, fails: [`the run failed: ${err && err.message}`] });
          log(`${n + 1} of ${CASES.length}: ${c.id}, the run failed: ${err && err.message}`);
        }
      }
    } finally {
      window.fetch = realFetch;
    }
    return { at: new Date().toISOString(), page: location.pathname, results };
  }

  if (location.pathname !== "/notes/sap/") {
    throw new Error('Open ' + "/notes/sap/" + ' on tools.nooutco.me first, then paste this again.');
  }
  return benchInPage(CASES, checkNote).then((report) => {
    console.table(report.results.map((r) => ({ case: r.id, pass: !r.fails.length, typed: r.typed ? r.typed.total : '-', seconds: r.seconds || '-', held: r.held && r.held.length ? r.held.join(', ') : '-', fails: r.fails.join(' | ') || '-' })));
    /* The table cuts a long cell short (9 Oct 2026: "One-Step Instructi...oals"),
       so each failure is also printed whole, one per line. */
    report.results.filter((r) => r.fails.length).forEach((r) => console.log(r.id + ' fails:\n  ' + r.fails.join('\n  ')));
    window.benchReport = report;
    try {
      if (!copyNow) throw new Error('no console copy()');
      copyNow(JSON.stringify(report, null, 2));
      console.log('The results and the notes are on your clipboard.');
    } catch (e) {
      console.log('To put the results on your clipboard, type copy(benchReport) and press Enter.');
    }
    return report;
  });
})();
